/*DNA追溯码:#龍芯⚡️2026-06-22-LONGHUN-FONT-WUWU-RENDERER-v1.0*/(function(global){'use strict';const WUWU_PALETTE=['#FF0000','#FFFF00','#00FFFF','#FFFFFF','#000000'];const PALETTE_SIZE=WUWU_PALETTE.length;function renderWuwu(text,options){options=options||{};let index=options.startIndex||0;const colorizeAll=options.colorizeAll!==false;const chars=[];for(const char of String(text||'')){if(char==='\n'){chars.push({char:char,colorClass:'',color:''});continue}const shouldColor=colorizeAll||isCJK(char);if(shouldColor){const colorIndex=index%PALETTE_SIZE;chars.push({char:char,colorClass:'wuwu-color-'+colorIndex,color:WUWU_PALETTE[colorIndex]});index++}else{chars.push({char:char,colorClass:'',color:''})}}return chars}function isCJK(char){const code=char.codePointAt(0);return(code>=0x4E00&&code<=0x9FFF)||(code>=0x3400&&code<=0x4DBF)||(code>=0xF900&&code<=0xFAFF)}if(typeof module!=='undefined'&&module.exports){module.exports={renderWuwu:renderWuwu,WUWU_PALETTE:WUWU_PALETTE}}if(typeof define==='function'&&define.amd){define(function(){return{renderWuwu:renderWuwu,WUWU_PALETTE:WUWU_PALETTE}})}if(typeof global!=='undefined'){global.renderWuwu=renderWuwu;global.WUWU_PALETTE=WUWU_PALETTE}})(typeof globalThis!=='undefined'?globalThis:typeof window!=='undefined'?window:typeof global!=='undefined'?global:this);
